# PR CI — dispatch-only (factory contract, see machine-sm.yml ci-workflow input).
# The machine loop's validation rules dispatch THIS workflow on PR heads;
# pushes fire no CI on their own. The job name MUST stay 'test' — it feeds
# the required branch-protection context (validation-checks: '["test"]').
name: CI

on:
  workflow_dispatch:

# One run per ref at a time; a fresh dispatch supersedes a stale one.
concurrency:
  group: ci-${{ github.ref }}
  cancel-in-progress: true

permissions:
  contents: read

jobs:
  test:
    name: test
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Install Dart SDK
        uses: dart-lang/setup-dart@v1
        with:
          sdk: stable

      # Separate step: a dependency-resolution failure is then visually
      # distinct from a test failure in the logs.
      - name: Resolve dependencies
        run: dart pub get

      # Expanded reporter: every test printed, failures carry the full
      # expected/actual diff and stack trace — logs must answer "why red".
      - name: Run tests
        run: dart test --reporter expanded
---
# Extra CI lane — a second monitored workflow for the self-heal polygon.
# Same tests as ci.yml, independent failure surface: when the self-heal
# drill breaks THIS workflow, it breaks the command itself (workflow-level
# infra failure), not the test code — the two lanes then produce two
# independent incidents with different cause classes.
# Self-heal keys incidents by FILENAME (wf:ci-extra.yml), one workflow per
# file is a GitHub invariant.
name: CI Extra

on:
  workflow_dispatch:
  push:
    branches:
      - main

# One run per ref at a time; a fresh dispatch supersedes a stale one.
concurrency:
  group: ci-extra-${{ github.ref }}
  cancel-in-progress: true

permissions:
  contents: read

jobs:
  test:
    name: test
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Install Dart SDK
        uses: dart-lang/setup-dart@v1
        with:
          sdk: stable

      - name: Resolve dependencies
        run: dart pub get

      # Mirror of ci.yml's test step. Kept textually identical on purpose:
      # the drill breaks it by editing THIS line (e.g. `dart testsss`),
      # ci.yml stays untouched — two lanes, two causes.
      - name: Run tests
        run: dart testsss --reporter expanded

    test('handles an empty string', () {
      expect(capitalize(''), '');
